// CF-03 · "Validate & Redact Résumé" (Run Once for All Items)
// 1) validates the résumé text (real error handling for incomplete / malformed data)
// 2) strips PII and protected-attribute proxies BEFORE any LLM sees the text (bias control)
const load = $('Load Application & Jobs').first().json.result;
const raw = String(load.application.resume_text || '');
const issues = [];    // blocking problems  -> status needs_info
const warnings = [];  // non-blocking flags -> screening continues, HR sees them

let text = raw.replace(/\r\n?/g, '\n').replace(/\u0000/g, '').replace(/[ \t ]+/g, ' ')
              .split('\n').map(l => l.trim()).join('\n').replace(/\n{3,}/g, '\n\n').trim();
const chars = text.length;
if (chars === 0) issues.push('EMPTY_RESUME');
else if (chars < 300) issues.push('TOO_SHORT');
if (chars > 40000) { text = text.slice(0, 40000); warnings.push('TRUNCATED_TO_40K_CHARS'); }

// garbled / mojibake detection (bad PDF extraction, wrong encoding, binary pasted as text)
const letters = (text.match(/[A-Za-z؀-ۿ]/g) || []).length;
const mojibake = (text.match(/[�]|Ã.|â€|Â/g) || []).length;
const letterRatio = chars ? letters / chars : 0;
if (chars >= 300 && (letterRatio < 0.5 || mojibake / chars > 0.01)) issues.push('GARBLED_TEXT');

// structure check (non-blocking)
const sections = {
  experience: /(^|\n)\s*(work )?(experience|employment|work history|professional experience|internships?|الخبرات?|الخبرة العملية)\b/i,
  education:  /(^|\n)\s*(education|academic|qualifications|التعليم|المؤهلات?)\b/i,
  skills:     /(^|\n)\s*(skills|technical skills|competencies|المهارات)\b/i,
};
const missing = Object.keys(sections).filter(k => !sections[k].test(text));
if (missing.length) warnings.push('MISSING_SECTIONS:' + missing.join('+'));

// prompt-injection detection (the score is deterministic, but HR must know)
const injection = /(ignore|disregard|forget)\s+(all\s+|any\s+|the\s+)?(previous|prior|above|earlier)\s+(instructions|prompts|rules)|system prompt|you are now|act as (the|a|an) |score (this|me|the) candidate|mark (this|me|the candidate) as|rate (this|me) (as )?\d/i;
if (injection.test(text)) {
  warnings.push('PROMPT_INJECTION_SUSPECTED');
  // drop the manipulative paragraph(s) so their fake claims are never scored
  text = text.split(/\n\s*\n/).filter(par => !injection.test(par)).join('\n\n');
}
if (/[؀-ۿ]{3,}/.test(text)) warnings.push('ARABIC_CONTENT');

// ---------------- redaction ----------------
const red = {};
const count = (k, n = 1) => { red[k] = (red[k] || 0) + n; };
// a) whole lines that only carry personal attributes (common on Egyptian CVs)
const personalLine = /^\s*(date of birth|d\.?o\.?b\.?|birth ?date|birthday|age|gender|sex|marital status|social status|military (status|service)|religion|nationality|national id|id number|place of birth|children|number of children|dependents|spouse|photo|picture|address|home address|تاريخ الميلاد|الجنس|الحالة الاجتماعية|الموقف من التجنيد|التجنيد|الديانة|الجنسية|الرقم القومي|العنوان)\b.*$/gim;
text = text.replace(personalLine, () => { count('personal_detail_line'); return ''; });
// b) inline identifiers
const rep = (key, re, out) => { text = text.replace(re, m => { count(key); return out; }); };
rep('email', /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL]');
rep('url', /\b(?:https?:\/\/|www\.)\S+|\b(?:linkedin\.com|github\.com|behance\.net)\/\S*/gi, '[LINK]');
rep('national_id', /\b[23]\d{13}\b/g, '[ID]');
text = text.replace(/(?:\+|\b0)[\d\s().-]{8,18}\d/g, m => {
  const digits = m.replace(/\D/g, '');
  if (digits.length >= 10 && digits.length <= 15) { count('phone'); return '[PHONE]'; }
  return m;
});
rep('age', /\b\d{2}\s*(years old|yrs old|y\/o|سنة)\b/gi, '[AGE]');
rep('birth_year', /\b(born|birth)\b[^\n]{0,30}\b(19|20)\d{2}\b/gi, '[REDACTED]');
rep('honorific', /\b(Mr|Mrs|Ms|Miss|Mx|Eng|Dr)\.\s*/g, '');
rep('gendered_word', /\b(he|she|him|his|hers|her|himself|herself|wife|husband|mother|father|son|daughter|male|female)\b/gi, 'they');
// c) the candidate's name: first non-empty line of a CV is the name (keep the headline after a separator)
const lines = text.split('\n');
const fi = lines.findIndex(l => l.trim());
if (fi >= 0) {
  const parts = lines[fi].split(/\s+[—–|-]\s+/);
  const looksLikeName = parts[0].length <= 60 && !/@|\d{3}/.test(parts[0]);
  if (looksLikeName) { lines[fi] = '[CANDIDATE]' + (parts.length > 1 ? ' — ' + parts.slice(1).join(' — ') : ''); count('name'); }
}
text = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();

return [{ json: {
  ok: issues.length === 0,
  issues, warnings, flags: warnings.slice(),
  redacted_text: text,
  redactions: red,
  original_chars: chars,
  application_id: load.application.id,
  app_code: load.application.app_code,
  job: load.job,
  open_jobs: load.open_jobs,
  rubric_version: load.rubric_version,
  started_at: Date.now()
} }];

