// CF-03 · "Normalize Profile" — accepts the profile from the cache OR from the LLM extractor
const cache = $('Check Profile Cache').first().json.result || {};
const fromCache = cache.found === true;
const p = fromCache ? (cache.profile || {}) : ($input.first().json.output || {});
const arr = v => Array.isArray(v) ? v : [];
const LEVELS = ['none','secondary','diploma','bachelor','master','phd'];
const LANG = ['basic','intermediate','professional','fluent','native'];
const profile = {
  headline: String(p.headline || '').slice(0, 160),
  summary: String(p.summary || '').slice(0, 600),
  skills: arr(p.skills).filter(s => s && s.name).slice(0, 80)
           .map(s => ({ name: String(s.name).slice(0, 60), evidence: String(s.evidence || '').slice(0, 200) })),
  roles: arr(p.roles).filter(r => r && r.title).slice(0, 15).map(r => ({
           title: String(r.title).slice(0, 120), domain: String(r.domain || '').slice(0, 80),
           months: Math.max(0, Math.min(600, Number(r.months) || 0)),
           is_internship: r.is_internship === true, is_volunteer: r.is_volunteer === true })),
  total_experience_years: Math.max(0, Number(p.total_experience_years) || 0),
  education: arr(p.education).slice(0, 6).map(e => ({
           level: LEVELS.includes(e.level) ? e.level : 'none', field: String(e.field || '').slice(0, 120),
           completed: e.completed !== false })),
  certifications: arr(p.certifications).slice(0, 20).map(c => ({
           name: String(c.name || c).slice(0, 120), status: c.status === 'in_progress' ? 'in_progress' : 'completed' })),
  languages: arr(p.languages).slice(0, 8).map(l => ({
           language: String(l.language || '').toLowerCase().trim(), level: LANG.includes(l.level) ? l.level : 'intermediate' })),
};
const issues = [];
if (!profile.skills.length && !profile.roles.length) issues.push('NO_SKILLS_OR_ROLES_EXTRACTED');
const query_text = [profile.headline, profile.summary, 'Skills: ' + profile.skills.map(s => s.name).join(', '),
                    'Roles: ' + profile.roles.map(r => r.title).join(', ')].join('\n').slice(0, 1500);
return [{ json: { profile, from_cache: fromCache, resume_hash: cache.resume_hash, query_text, issues } }];

// CF-03 · "Score Against Rubric" — deterministic, explainable scoring (no LLM decides the score)
// Weights: must-have 40 · experience 20 · nice-to-have 15 · education 6 · certifications 4 · languages 10 · hire-pattern 5
const ctx  = $('Validate & Redact Résumé').first().json;
const np   = $('Normalize Profile').first().json;
const prof = np.profile;
const similar  = ($('Collect Similar Roles').first().json.similar_roles || []).filter(d => d && d.document);
const patterns = ($('Collect Hire Patterns').first().json.patterns || []).filter(d => d && d.document);
const RUBRIC = 'cf-rubric-1.0';
const W = { must: 40, exp: 20, nice: 15, edu: 6, cert: 4, lang: 10, pattern: 5 };

const norm = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9؀-ۿ+#&\/.\s-]/g, ' ').replace(/\s+/g, ' ').trim();
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const has = (hay, term) => { const t = norm(term); if (!t) return false;
  return new RegExp('(^|[^a-z0-9+#])' + esc(t) + '($|[^a-z0-9+#])').test(hay); };
const r1 = x => Math.round(x * 10) / 10;

const textN = ' ' + norm(ctx.redacted_text) + ' ';
// LLM skills only count when their evidence quote really exists in the résumé (anti-hallucination / anti-injection)
const skills = (prof.skills || []).map(s => {
  const ev = norm(s.evidence);
  const words = ev.split(' ').filter(w => w.length > 3);
  const verified = ev.length >= 3 && (textN.includes(ev.slice(0, 50)) || (words.length > 0 && words.filter(w => textN.includes(w)).length / words.length >= 0.8));
  return { name: norm(s.name), verified };
});
const skillHay = ' ' + skills.filter(s => s.verified).map(s => s.name).join(' | ') + ' ';
const unverified = skills.filter(s => !s.verified).map(s => s.name);

const matchGroup = g => {
  const terms = [g.label, ...(g.aliases || [])];
  for (const t of terms) if (has(textN, t)) return { label: g.label, matched: true, via: 'résumé text', term: t };
  for (const t of terms) if (has(skillHay, t)) return { label: g.label, matched: true, via: 'verified extracted skill', term: t };
  return { label: g.label, matched: false };
};
const LV = { none: 0, secondary: 1, diploma: 2, bachelor: 3, master: 4, phd: 5 };
const LL = { basic: 1, intermediate: 2, professional: 3, fluent: 4, native: 5 };
const LLname = n => Object.keys(LL).find(k => LL[k] === n) || 'not stated';

// language levels: LLM levels + hard evidence in the text (CEFR / IELTS / TOEFL)
const langHave = {};
for (const l of prof.languages || []) { const k = norm(l.language); langHave[k] = Math.max(langHave[k] || 0, LL[l.level] || 0); }
if (/\b(c2)\b|native english/.test(textN)) langHave.english = Math.max(langHave.english || 0, 4);
else if (/\bc1\b|ielts\s*(7|8|9)|toefl\s*(1[01]\d|9\d)/.test(textN)) langHave.english = Math.max(langHave.english || 0, 4);
else if (/\bb2\b|ielts\s*6/.test(textN)) langHave.english = Math.max(langHave.english || 0, 3);

function scoreJob(job, usePatterns) {
  // 1) must-have skills
  const must = (job.must_have_skills || []).map(matchGroup);
  const mustHit = must.filter(m => m.matched).length;
  const mustPts = must.length ? W.must * mustHit / must.length : W.must;
  // 2) relevant experience (internships count 50%, volunteering 25%; more experience is NEVER penalised)
  const kws = job.experience_keywords || [];
  let relMonths = 0; const relRoles = [];
  for (const r of prof.roles || []) {
    const hay = ' ' + norm(r.title + ' ' + r.domain) + ' ';
    if (kws.some(k => has(hay, k))) {
      const w = r.is_volunteer ? 0.25 : (r.is_internship || /\bintern/.test(norm(r.title))) ? 0.5 : 1;
      relMonths += r.months * w; relRoles.push(r.title + ' (' + r.months + ' mo × ' + w + ')');
    }
  }
  const relYears = r1(relMonths / 12);
  const minY = Number(job.min_years) || 0;
  const expPts = minY === 0 ? W.exp * (0.6 + 0.4 * Math.min(1, relYears)) : W.exp * Math.min(1, relYears / minY);
  // 3) nice-to-have
  const nice = (job.nice_to_have_skills || []).map(matchGroup);
  const niceHit = nice.filter(m => m.matched).length;
  const nicePts = nice.length ? W.nice * niceHit / nice.length : W.nice;
  // 4) education (level + field; the institution is NEVER used — prestige bias)
  const er = job.education_requirement || {};
  const need = LV[er.min_level] || 0;
  const eds = prof.education || [];
  const best = eds.reduce((m, e) => Math.max(m, (LV[e.level] || 0) - (e.completed === false ? 0.5 : 0)), 0);
  const fields = er.fields || [];
  const fieldOk = fields.length === 0 || eds.some(e => fields.some(f => has(' ' + norm(e.field) + ' ', f)));
  const levelFactor = need === 0 || best >= need ? 1 : best >= need - 0.5 ? 0.75 : best >= need - 1 ? 0.5 : 0.25;
  const eduPts = W.edu * (0.67 * levelFactor + (fieldOk ? 0.33 : 0));
  // 5) certifications (any preferred certification = full points; none listed by the job = full points)
  const certHay = ' ' + norm((prof.certifications || []).map(c => c.name).join(' | ')) + ' ';
  const certs = (job.preferred_certifications || []).filter(g => [g.label, ...(g.aliases || [])].some(a => has(certHay, a) || has(textN, a)));
  const certPts = (job.preferred_certifications || []).length ? (certs.length ? W.cert : 0) : W.cert;
  // 6) languages
  const langReq = job.language_requirements || [];
  const langs = langReq.map(r => { const h = langHave[norm(r.language)] || 0; const n = LL[r.min_level] || 3;
    return { language: r.language, required: r.min_level, have: LLname(h), ratio: r1(Math.min(1, h / n) * 100) / 100 }; });
  const langPts = langReq.length ? W.lang * langs.reduce((s, l) => s + l.ratio, 0) / langReq.length : W.lang;
  // 7) past-hire PATTERN alignment (capped at 5 points by design — historical data must not dominate)
  let pat = null;
  if (usePatterns) for (const d of patterns) {
    const md = d.document.metadata || {};
    if (md.role_family && md.role_family !== job.role_family) continue;
    const ks = String(md.key_skills || '').split('|').map(s => s.trim()).filter(Boolean);
    const hit = ks.filter(k => has(textN, k) || has(skillHay, k));
    const ratio = ks.length ? hit.length / ks.length : 0;
    if (!pat || ratio > pat.ratio) pat = { pattern_id: md.pattern_id, ratio, matched: hit, total: ks.length };
  }
  const patPts = pat ? W.pattern * pat.ratio : 0;

  const total = r1(mustPts + expPts + nicePts + eduPts + certPts + langPts + patPts);
  const band = total >= 75 ? 'Strong match' : total >= 60 ? 'Potential match' : total >= 40 ? 'Weak match' : 'Not a match';
  const missingMust = must.filter(m => !m.matched).map(m => m.label);
  return {
    job_id: job.id, title: job.title, score: total, band,
    criteria: [
      { criterion: 'Must-have skills', points: r1(mustPts), max: W.must, detail: `${mustHit}/${must.length} matched`, items: must },
      { criterion: 'Relevant experience', points: r1(expPts), max: W.exp, detail: `${relYears} relevant years (required ${minY})`, items: relRoles },
      { criterion: 'Nice-to-have skills', points: r1(nicePts), max: W.nice, detail: `${niceHit}/${nice.length} matched`, items: nice },
      { criterion: 'Education', points: r1(eduPts), max: W.edu, detail: `level ${levelFactor === 1 ? 'meets' : 'below'} ${er.min_level || 'none'}; field ${fieldOk ? 'relevant' : 'not listed'}`, items: eds },
      { criterion: 'Certifications', points: r1(certPts), max: W.cert, detail: certs.length ? certs.map(c => c.label).join(', ') : ((job.preferred_certifications || []).length ? 'none of the preferred' : 'not required'), items: [] },
      { criterion: 'Languages', points: r1(langPts), max: W.lang, detail: langs.map(l => `${l.language}: ${l.have} vs ${l.required}`).join('; ') || 'not required', items: langs },
      { criterion: 'Past-hire pattern alignment (capped)', points: r1(patPts), max: W.pattern, detail: pat ? `${pat.matched.length}/${pat.total} pattern skills (${pat.pattern_id})` : 'no pattern available', items: pat ? pat.matched : [] },
    ],
    summary: { must_have: `${mustHit}/${must.length}`, missing_must_have: missingMust, relevant_years: relYears, nice_to_have: `${niceHit}/${nice.length}` },
  };
}

const job = ctx.job;
const main = scoreJob(job, true);
// alternatives = other OPEN roles that the RAG search found similar to this profile (role disambiguation)
const seen = new Set([job.id]); const altIds = [];
for (const d of similar) { const id = (d.document.metadata || {}).job_id; if (id && !seen.has(id)) { seen.add(id); altIds.push({ id, distance: d.score }); } }
const alternatives = altIds.slice(0, 3).map(a => {
  const j = (ctx.open_jobs || []).find(o => o.id === a.id); if (!j) return null;
  const s = scoreJob(j, false);
  return { job_id: j.id, title: j.title, score: s.score, band: s.band, similarity: a.distance != null ? r1((1 - a.distance) * 100) / 100 : null };
}).filter(Boolean).filter(a => a.score >= 60).sort((a, b) => b.score - a.score).slice(0, 2);

const flags = [...(ctx.flags || []), ...(np.issues || [])];
if (unverified.length) flags.push('UNVERIFIED_SKILL_CLAIMS:' + unverified.slice(0, 5).join('|'));
const recommendation = flags.includes('PROMPT_INJECTION_SUSPECTED') ? 'Manual review required — possible manipulation attempt'
  : main.score >= 75 ? 'Shortlist for HR review'
  : main.score >= 60 ? 'HR to review' : 'Low fit — HR to confirm (never auto-rejected)';
const c = main.criteria;
const explanation = `${main.band} — ${main.score}/100 for ${job.title} (${job.id}). ` +
  `Must-have ${main.summary.must_have}${main.summary.missing_must_have.length ? ' (missing: ' + main.summary.missing_must_have.join(', ') + ')' : ''}; ` +
  `${c[1].detail}; nice-to-have ${main.summary.nice_to_have}; ${c[5].detail}. ` +
  (alternatives.length ? 'Also fits: ' + alternatives.map(a => `${a.title} (${a.score})`).join(', ') + '. ' : '') +
  (flags.length ? 'Flags: ' + flags.join(', ') + '.' : '');

return [{ json: {
  application_id: ctx.application_id, app_code: ctx.app_code, outcome: 'screened',
  score: main.score, band: main.band, recommendation, explanation,
  breakdown: { rubric: RUBRIC, weights: W, criteria: main.criteria, summary: main.summary },
  alternatives, flags, profile: prof, redactions: ctx.redactions, redacted_resume: ctx.redacted_text,
  resume_hash: np.resume_hash, from_cache: np.from_cache, rubric_version: RUBRIC,
  duration_ms: Date.now() - ctx.started_at
} }];

const s = $('Score Against Rubric').first().json;
return [{ json: { ok: true, status: $input.first().json.result.status, application_id: s.application_id, app_code: s.app_code,
  score: s.score, band: s.band, recommendation: s.recommendation, explanation: s.explanation, alternatives: s.alternatives, flags: s.flags,
  from_cache: s.from_cache, duration_ms: s.duration_ms } }];
